def point_in_triangle(p, a, b, c):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    c1 = cross(a, b, p)
    c2 = cross(b, c, p)
    c3 = cross(c, a, p)
    # Non-degenerate triangle: a, b, c are not colinear, so signs 1, -1, 1 are defined,
    # and colinearity is only possible inside the triangle
    return (c1 >= 0 and c2 >= 0 and c3 >= 0 and c1 <= 0 and c2 <= 0 and c3 <= 0)
```

