def classify_triangle_by_sides(p1, p2, p3):
    import math
    d1 = math.hypot(p2[0] - p1[0], p2[1] - p1[1])
    d2 = math.hypot(p3[0] - p2[0], p3[1] - p2[1])
    d3 = math.hypot(p1[0] - p3[0], p1[1] - p3[1])
    s = {d1, d2, d3}
