import math

def is_square(p1, p2, p3, p4):
    def dist2(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
    def dot(p, q):
        return p[0] * q[0] + p[1] * q[1]

    def side_pairs():
        return [(p1, p2), (p2, p3), (p3, p4), (p4, p1)]
    def diagonals():
        return [(p1, p3), (p2, p4)]

    sides = [dist2(p, q) for p, q in side_pairs()]
    diagon = [dist2(p, q) for p, q in diagonals()]

    # Check all sides equal and diagonals equal
    if not all(math.isclose(s, sides[0]) for s in sides):
        return False
    if not all(math.isclose(d, diagon[0]) for d in diagon):
        return False

    # Each diagonal should be twice a side and perpendicular to the adjacent sides
    for (u, v), (w, x) in zip(side_pairs(), diagonals()):
        if not math.isclose(diagon[0], 2 * sides[0]):
            return False
        if not math.isclose(dot(v, w), 0):  # dot product of adjacent side and diagonal
            return False
    return True
```

The function rejects a shape as soon as one of its sides differs from the others, before it even looks at the diagonals. If the sides all match, it then compares both diagonals against twice that shared distance and confirms each diagonal is perpendicular to its neighboring side through the dot product. A rectangle passes the side and diagonal checks but its diagonals are not perpendicular to the adjacent sides, so only true squares survive. Comparisons use floating-point equality with insignificant error tolerated.

