def flood_fill(grid, sr, sc, new_value):
    # Copy the grid to avoid modifying the input
    result = [row[:] for row in grid]
    original = result[sr][sc]
    if original == new_value:
        return result  # No change is needed
    # Fringe of cells to visit
    fringe = [(sr, sc)]
    while fringe:
        r, c = fringe.pop()
        result[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(result) and 0 <= nc < len(result[nr]):
                if result[nr][nc] == original:
                    fringe.append((nr, nc))
    return result
```

