```python
def parse_url_parts(url):
    #scheme is everything before the first colon slash slash;
    #everything from there up to the next slash or question mark is the host;
    #then comes the path, which starts at the slash and ends at the question mark,
    #and the query, which is everything after the question mark.
    colonslashpos = url.find('://')
    if colonslashpos == -1:
        raise ValueError('Not a valid URL')
    rest = url[colonslashpos + 3:]
    if '/' in rest and '?' in rest:
        slashpos, qmarkpos = rest.index('/'), rest.index('?')
    elif '/' in rest:
        slashpos, qmarkpos = rest.index('/'), -1
    elif '?' in rest:
        slashpos, qmarkpos = -1, rest.index('?')
    else:
        slashpos, qmarkpos = -1, -1
    scheme = url[:colonslashpos]
    host = rest[:min(slashpos, qmarkpos)]
    path = rest[slashpos:qmarkpos] if slashpos != -1 else ''
    query = rest[qmarkpos + 1:] if qmarkpos != -1 else ''
    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
