    # Split the rest at the first '/' or '?'
    separator = '/' if '/' in rest else '?'
    separator_pos = rest.find(separator)
    if separator_pos == -1:
        # No separator; everything after the colon-slash-slash is the host
        host, rest = rest, ''
    else:
        host, rest = rest[:separator_pos], rest[separator_pos:]
    # The rest contains the path and query
    if rest.startswith('/'):
        path = rest[0:rest.find('?') if '?' in rest else None]
    elif rest.startswith('?'):
        path = ''
        rest = rest[1:]
    else:
        path = ''
    # The rest after that is the query
    query = rest.split('?', 1)[0] if '?' in rest else ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

