def rectangle_intersection_area(r1, r2):
    def overlap(a, b):
        # The overlap starts at the maximum left end and ends at the minimum right end.
        # If the left end is at or after the right end, there is no overlap.
        left = max(a[0], b[0])
        right = min(a[2], b[2])
        if left >= right:
            return 0
        # The height in perpendicular dimension is bounded in the same way.
        bottom = max(a[1], b[1])
        top = min(a[3], b[3])
        if bottom >= top:
            return 0
        return (right - left) * (top - bottom)
    return overlap(r1, r2)
