def spiral_order(grid):
    result = []
    if not grid or not grid[0]:
        return result
    height = len(grid)
    width = len(grid[0])
    for layer in range((min(height, width) + 1) // 2):
        top, bottom, left, right = layer, height - 1 - layer, layer, width - 1 - layer
        # Left to right along the top row
        for col in range(left, right + 1):
            result.append(grid[top][col])
        # Top to bottom along the right column
        for row in range(top + 1, bottom + 1):
            result.append(grid[row][right])
        # Right to left along the bottom row, skipping the rightmost cell
        if top < bottom:
            for col in range(right - 1, left - 1, -1):
                result.append(grid[bottom][col])
        # Bottom to top along the left column, skipping the bottommost and topmost
        if left < right:
            for row in range(bottom - 1, top, -1):
                result.append(grid[row][left])
    return result
```

