def spiral_order(grid):
    """Visit elements top row left to right, right column top to bottom,
    bottom row right to left, left column bottom to top, then spiral inward,
    returning each cell once in order. An empty grid gives an empty list."""
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    result = []
    while len(result) < rows * cols:
        # Top row
        for j in range(cols):
            if not visited[0][j]:
                result.append(grid[0][j])
                visited[0][j] = True
        # Right column
        for i in range(1, rows):
            if not visited[i][cols - 1]:
                result.append(grid[i][cols - 1])
                visited[i][cols - 1] = True
        if rows > 1:
            # Bottom row, left to right
            for j in range(cols - 1, -1, -1):
                if not visited[rows - 1][j]:
                    result.append(grid[rows - 1][j])
                    visited[rows - 1][j] = True
            # Left column, bottom to top
            for i in range(rows - 2, 0, -1):
                if not visited[i][0]:
                    result.append(grid[i][0])
                    visited[i][0] = True
    return result
```

