def count_islands(grid):
    w = len(grid)
    if not w:
        return 0
    h = len(grid[0])
    visited = [[False] * h for _ in range(w)]

    def flood(x, y):
        if not (0 <= x < w and 0 <= y < h) or visited[x][y] or grid[x][y] == 0:
            return
        visited[x][y] = True
        for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            flood(x + dx, y + dy)

    result = 0
    for x in range(w):
        for y in range(h):
            if not visited[x][y] and grid[x][y]:
                flood(x, y)
                result += 1
    return result
```

