    allowed = []
    n = len(timestamps)
    for i in range(n):
        t = timestamps[i]
        # Count how many times, among the first i+1, fall in the half-open window
        k = 0
        while k <= i and timestamps[k] <= t:
            if timestamps[k] > t - window:
                k += 1
            else:
                break
        if k > i:
            k = i + 1
        allowed.append(k <= limit)
    return allowed
