    full_cycle_b = red_b + green_b + yellow_b

    count = 0
    for t in range(n_ticks):
        # current phase for light a
        pos_a = t % full_cycle_a
        if pos_a < red_a:
            phase_a = 'RED'
        elif pos_a < red_a + green_a:
            phase_a = 'GREEN'
        else:
