        if pos_b < red_b:
            phase_b = 'RED'
        elif pos_b < red_b + green_b:
            phase_b = 'GREEN'
        else:
            phase_b = 'YELLOW'
        if phase_a == 'GREEN' and phase_b == 'GREEN':
