def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]
    queue = [(sr, sc)]
    while queue:
        r, c = queue.pop()
        if grid[r][c] != old_value:
            continue
        grid[r][c] = new_value
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                queue.append((nr, nc))
    return [row[:] for row in grid]
