def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    from copy import deepcopy
    from collections import deque
    grid_copy = deepcopy(grid)
    original = grid_copy[sr][sc]
    if original == new_value or original != grid[sr][sc]:
        return grid_copy
    queue = deque()
    queue.append((sr, sc))
    while queue:
        r, c = queue.popleft()
        if grid[r][c] != original:
            continue
        grid_copy[r][c] = new_value
        if r > 0 and grid_copy[r - 1][c] == original:
            queue.append((r - 1, c))
        if r < len(grid) - 1 and grid_copy[r + 1][c] == original:
            queue.append((r + 1, c))
        if c > 0 and grid_copy[r][c - 1] == original:
            queue.append((r, c - 1))
        if c < len(grid[0]) - 1 and grid_copy[r][c + 1] == original:
            queue.append((r, c + 1))
    return grid_copy
```

