def is_checkerboard(grid):
    """A board is a checkerboard if every cell differs from its immediate
    neighbours and at most two alternating values are used."""

    height = len(grid)
    width = len(grid[0]) if height else 0
    if height == 0 or width == 0:
        return True  # Empty grid is allowed by the task
    if height == 1 and width == 1:
        return True  # A single cell is also allowed

