        for j in range(width):
            for (di, dj) in [(0, 1), (1, 0)]:  # Right and down
                ni, nj = i + di, j + dj
                if 0 <= ni < height and 0 <= nj < width:
                    if grid[i][j] == grid[ni][nj]:
                        return False

    parity = set()
    for i in range(height):
        for j in range(width):
            parity.add((i + j) % 2)
            if (i + j) % 2 == 0:
                val = 1
            else:
