def is_convex_polygon(points):
    if len(points) < 3:
        return False
    if set(points) == 2:
        return False
    pos = 0
    neg = 0
    for i in range(len(points)):
        x0, y0 = points[i]
        x1, y1 = points[(i + 1) % len(points)]
        x2, y2 = points[(i + 2) % len(points)]
        cross = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)
        if cross > 0:
            pos += 1
        elif cross < 0:
            neg += 1
    return not (pos and neg)
```

