def flood_fill(grid, sr, sc, new_value):
    out = [row[:] for row in grid]
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return out
    base = grid[sr][sc]
    if new_value == base:
        return out
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        if out[r][c] == base:
            out[r][c] = new_value
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    stack.append((nr, nc))
    return out
```

